Here's a Python program that meets your requirements. This program uses a dictionary to store the contacts and provides methods to add, remove, and search contacts.

```python
class Phonebook:
    def __init__(self):
        self.contacts = {}

    def add_contact(self, name, phone_number):
        if name not in self.contacts:
            self.contacts[name] = phone_number
            print(f"Contact added: {name}, Phone: {phone_number}")
        else:
            print(f"Contact {name} already exists. Cannot add duplicate contact.")

    def remove_contact(self, name):
        if name in self.contacts:
            del self.contacts[name]
            print(f"Contact removed: {name}")
        else:
            print(f"Contact {name} not found. Cannot remove contact.")

    def search_contact(self, name):
        if name in self.contacts:
            print(f"Contact found: {name}, Phone: {self.contacts[name]}")
        else:
            print(f"Contact {name} not found.")

# Example usage
phonebook = Phonebook()

# Add contact
phonebook.add_contact("John Doe", "123-456-7890")

# Remove contact
phonebook.remove_contact("John Doe")

# Search contact
phonebook.search_contact("John Doe")
```

This program will create a simple phonebook app with the specified functionality.
